 void RemoveOtherBluetoothModels(){var other=Prefs.Devices.Where(d=>d.Model=="A2687"&&(A2687Model.OtherSerial(d.SerialNumber)||Prefs.ExcludedBluetoothDevices.Any(e=>DeviceRegistry.Same(d,e)))).ToArray();if(other.Length==0)return;if(!File.Exists(Path.Combine(Store.Root,"settings-before-model-filter.json")))Store.Write("settings-before-model-filter.json",Prefs);foreach(var d in other){Prefs.Devices.Remove(d);DeviceRegistry.Remember(Prefs.ExcludedBluetoothDevices,d);}Store.Write("settings.json",Prefs);}
 void Remember(DeviceState d){DeviceRegistry.Remember(Prefs.Devices,DeviceRegistry.FromState(d));Save();}
 void GatePort(){if(!Prefs.AllowPortControl)throw new InvalidOperationException("请先在设置中打开“允许端口开关”。");if(!Current.Connected)throw new IOException("请先连接充电器");}
 void Experimental(){if(!Prefs.AllowExperimental)throw new InvalidOperationException("请先在设置中打开“允许实验性控制”。");}
 void Require250(){if(Current.Model!="A2345")throw new InvalidOperationException("此功能适用于 250W（A2345）");}
 int Port(JsonObject a){int p=I(a,"port");if(p<0||p>=Current.Ports.Count)throw new ArgumentException("无效端口");return p;}
 async Task Command(ushort opcode,IEnumerable<Field> fields,bool longFields=false){if(!Current.Connected)throw new IOException("请先连接充电器");if(Current.Demo){AddLog($"模拟命令 0x{opcode:X4}");return;}if(Current.Model=="A2687")await ble.Command(opcode,fields);else await cloud.Command(opcode,fields,longFields);AddLog($"命令 0x{opcode:X4} 已由设备确认");}
 async Task SetPort(int p,bool on){GatePort();if(p<0||p>=Current.Ports.Count)throw new ArgumentException("无效端口");if(Current.Demo){foreach(var port in demo.Ports.Where(x=>demo.Model=="A2345"?Math.Min(x.Index,4)==Math.Min(p,4):x.Index==p))port.On=on;Changed();return;}await Command(0x207,Current.Model=="A2687"?[Wire.U8(0xa2,p),Wire.U8(0xa3,on?1:0)]:[Wire.F(0xa2,(byte)Math.Min(p,4)),Wire.F(0xa3,(byte)(on?1:0))]);}
 async Task Setting(string key,int value){bool c=Current.Model=="A2345";ushort op;int min=0,max;
  switch(key){case "brightness":op=0x204;min=c?20:0;max=100;if(c&&value%5!=0)throw new ArgumentException("亮度步进为 5%");break;case "timeout":op=0x203;max=4;break;case "language":if(c)throw new ArgumentException("250W 无此控制接口");op=0x202;max=3;break;case "orientation":if(c)throw new ArgumentException("250W 无此控制接口");op=0x20b;max=3;break;case "gyro":if(c)throw new ArgumentException("250W 无此控制接口");op=0x20d;max=1;break;case "fixed":if(c)throw new ArgumentException("250W 无此控制接口");Experimental();op=0x205;max=1;break;case "mode":Experimental();op=0x206;min=c?1:0;max=c?4:1;break;
   case "knob":Require250();Experimental();op=0x20e;max=1;break;case "hour":Require250();Experimental();op=0x210;max=1;break;case "holiday":Require250();Experimental();op=0x20f;max=1;break;case "showTime":Require250();Experimental();op=0x222;max=1;break;case "priority":Require250();Experimental();op=0x20c;max=15;if(System.Numerics.BitOperations.PopCount((uint)value)>2)throw new ArgumentException("最多选择两个优先端口");break;
   case "ufcs":Require250();Experimental();op=0x215;max=1;break;case "identify":Require250();Experimental();op=0x223;max=1;break;case "compatibility":Require250();Experimental();op=0x214;max=1;break;default:throw new ArgumentException("未知设备设置");}
  if(value<min||value>max)throw new ArgumentException("参数超出范围");if(Current.Demo){demo.Settings[key]=value;Changed();return;}
  if(c&&key is "identify" or "compatibility"){string name=key=="identify"?"charging_device_identity_status_default_true":"compatibility_status";await api.Post("mini_power/v1/app/setting/set_"+name,new JsonObject{["device_sn"]=Current.Id,[name]=value});}
  await Command(op,c?[Wire.F(0xa2,(byte)(key=="compatibility"?1-value:value))]:[Wire.U8(0xa2,value)]);
 }
 async Task Custom(JsonObject a){Experimental();var watts=Numbers(a,"watts");bool c=Current.Model=="A2345";if(watts.Length!=(c?5:3)||watts.Sum(x=>(int)x)>(c?250:160))throw new ArgumentException("自定义功率总和超出范围");for(int i=0;i<watts.Length;i++){int limit=c&&i==4?24:c&&i>0?(Prefs.Country=="CN"?120:100):140;if(watts[i]!=0&&(watts[i]<15||watts[i]>limit))throw new ArgumentException("单口功率超出范围");}if(c&&!new byte[]{0,15,24}.Contains(watts[4]))throw new ArgumentException("USB-A 组仅支持 0 / 15 / 24W");int number=I(a,"number",1);if(number<1||number>(c?4:1))throw new ArgumentException("自定义模式编号无效");byte[] profile=new[]{(byte)number,(byte)(B(a,"autoExit")?1:0)}.Concat(watts).ToArray();var f=new List<Field>{c?Wire.F(0xa2,5):Wire.U8(0xa2,2),c?Wire.F(0xa3,profile):Wire.Block(0xa3,profile)};if(c&&a["protocols"] is JsonArray){var flags=Numbers(a,"protocols");if(flags.Length!=4||flags.Any(x=>x>127))throw new ArgumentException("协议选项无效");f.Add(Wire.F(0xa4,flags.SelectMany(x=>new byte[]{x,0,0}).ToArray()));}await Command(0x206,f);if(Current.Demo)demo.Settings["mode"]=c?5:2;}
 async Task Theme(JsonObject a){Require250();Experimental();int kind=I(a,"kind");if(!new[]{0,1,2,3,5}.Contains(kind))throw new ArgumentException("无效主题");var fields=new List<Field>{Wire.F(0xa2,(byte)((B(a,"clockOn")?0x80:0)|kind)),Wire.F(0xa3,kind>=3?BitConverter.GetBytes(uint.Parse(S(a,"themeId"))):[]),Wire.F(0xa4,BitConverter.GetBytes(ParseUInt(S(a,"crc")))),Wire.F(0xa5,BitConverter.GetBytes(0xffffffffu))};string url=kind<3?$"assets/img/a2345/icl_a2345_theme{kind+1}.png":S(a,"url");if(url.Length>1024||kind==3&&Encoding.UTF8.GetByteCount(url)>254)throw new ArgumentException("主题地址太长");fields.Add(Wire.F(kind==5?0xa7:0xa6,Encoding.UTF8.GetBytes(url)));await Command(0x205,fields,kind==5);}
 static uint ParseUInt(string s){if(s.StartsWith("0x"))return Convert.ToUInt32(s[2..],16);return uint.TryParse(s,out var n)?n:uint.TryParse(s,System.Globalization.NumberStyles.HexNumber,null,out n)?n:0;}
 async Task<object?> CloudList(string kind){Require250();if(Current.Demo)return new JsonArray();string path=kind switch{"modes"=>"charging/get_charging_mode_list","themes"=>"style/get_clock_screensavers","pictures"=>"style/get_manual_clock_screensavers",_=>throw new ArgumentException("未知列表")};var body=kind=="themes"?new JsonObject{["product_code"]="A2345"}:kind=="pictures"?new JsonObject{["sn"]=Current.Id}:new JsonObject{["device_sn"]=Current.Id};return await api.Post("mini_power/v1/app/"+path,body);}
 async Task CloudChange(string kind,JsonObject value){Require250();Experimental();if(Current.Demo)return;string path=kind switch{"addMode"=>"charging/add_charging_mode","updateMode"=>"charging/update_charging_mode","deleteMode"=>"charging/delete_charging_mode","deletePicture"=>"style/delete_manual_clock_screensavers",_=>throw new ArgumentException("未知云端操作")};if(kind=="addMode")value["device_sn"]=Current.Id;await api.Post("mini_power/v1/app/"+path,value);}
 async Task<object?> Upload(){Experimental();if(!Current.Connected)throw new IOException("请先连接充电器");var dialog=new Microsoft.Win32.OpenFileDialog{Filter="图片|*.jpg;*.jpeg;*.png;*.bmp"};if(dialog.ShowDialog()!=true)return false;byte[] jpg=ImageTools.Jpeg(dialog.FileName,Current.Model=="A2687"?240:480,Current.Model=="A2687"?240:200);if(Current.Demo)return true;if(Current.Model=="A2687")await ble.UploadCover(jpg,(uint)DateTimeOffset.UtcNow.ToUnixTimeSeconds(),p=>Notify?.Invoke(new{type="progress",value=p}));else await api.Upload(jpg,Current.Id);return true;}
 object ReadHistory(int days){days=Math.Clamp(days,1,366);var end=DateTimeOffset.Now;var start=new DateTimeOffset(end.LocalDateTime.Date).AddDays(1-days);var points=history.Read(start,end);return new{kwh=EnergyHistory.Kwh(points),cost=EnergyHistory.Kwh(points)*Prefs.Tariff,currency=Prefs.Currency,daily=points.GroupBy(p=>p.At.LocalDateTime.ToString("yyyy-MM-dd")).Select(g=>new{date=g.Key,kwh=EnergyHistory.Kwh(g)}),samples=points.TakeLast(3000).ToArray()};}
 object Export(string format,int days){var end=DateTimeOffset.Now;var start=new DateTimeOffset(end.LocalDateTime.Date).AddDays(1-Math.Clamp(days,1,366));var points=history.Read(start,end);bool csv=format=="csv";var d=new Microsoft.Win32.SaveFileDialog{FileName="ANKER-"+DateTime.Now.ToString("yyyyMMdd")+(csv?".csv":".json"),Filter=csv?"CSV|*.csv":"JSON|*.json"};if(d.ShowDialog()!=true)return false;if(csv){var sb=new StringBuilder("time,device_id,model,port,power_w\r\n");foreach(var p in points)for(int i=0;i<p.Watts.Length;i++)sb.Append(p.At.ToString("O")).Append(',').Append('"').Append(p.Device.Replace("\"","\"\"")).Append("\",").Append(p.Model).Append(',').Append(i+1).Append(',').Append(p.Watts[i].ToString("G17",System.Globalization.CultureInfo.InvariantCulture)).Append("\r\n");File.WriteAllText(d.FileName,sb.ToString(),new UTF8Encoding(true));}else File.WriteAllText(d.FileName,JsonSerializer.Serialize(new{start,end,tariff=Prefs.Tariff,currency=Prefs.Currency,kwh=EnergyHistory.Kwh(points),samples=points},Store.Json));return true;}
 void UpdatePrefs(JsonObject a){if(a["startWithWindows"]!=null){windowsStartup.Set(B(a,"startWithWindows"));Prefs.StartWithWindows=windowsStartup.Enabled;}if(a["desktopWidgetEnabled"]!=null)Prefs.DesktopWidgetEnabled=B(a,"desktopWidgetEnabled");if(a["desktopWidgetLocked"]!=null)Prefs.DesktopWidgetLocked=B(a,"desktopWidgetLocked");if(a["desktopWidgetTopmost"]!=null)Prefs.DesktopWidgetTopmost=B(a,"desktopWidgetTopmost");if(a["powerRefreshSeconds"]!=null){if(!int.TryParse(S(a,"powerRefreshSeconds"),out int seconds)||seconds<0||seconds>10)throw new ArgumentException("刷新间隔须为程序默认或 1–10 秒");Prefs.PowerRefreshSeconds=seconds;}if(a["allowPortControl"]!=null)Prefs.AllowPortControl=B(a,"allowPortControl");if(a["allowExperimental"]!=null)Prefs.AllowExperimental=B(a,"allowExperimental");if(a["closeToTray"]!=null)Prefs.CloseToTray=B(a,"closeToTray");if(a["language"]!=null)Prefs.Language=S(a,"language")=="en"?"en":"zh";if(a["tariff"]!=null){if(!double.TryParse(S(a,"tariff"),out double n)||!double.IsFinite(n)||n<0||n>10000)throw new ArgumentException("电价无效");Prefs.Tariff=n;}if(a["currency"]!=null)Prefs.Currency=S(a,"currency")[..Math.Min(8,S(a,"currency").Length)];if(a["trayTemplate"]!=null)Prefs.TrayTemplate=S(a,"trayTemplate")[..Math.Min(200,S(a,"trayTemplate").Length)];if(a["ownerId"]!=null)Prefs.OwnerId=S(a,"ownerId");}
 public void Dispose(){disposed=true;StopCloudRetries();ble.Dispose();cloud.Dispose();api.Dispose();matter.Dispose();}
