public static class ImageTools {
 public static byte[] Jpeg(string file,int width,int height){var b=new System.Windows.Media.Imaging.BitmapImage();b.BeginInit();b.CacheOption=System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;b.UriSource=new Uri(file);b.EndInit();double scale=Math.Max((double)width/b.PixelWidth,(double)height/b.PixelHeight);var scaled=new System.Windows.Media.Imaging.TransformedBitmap(b,new System.Windows.Media.ScaleTransform(scale,scale));var crop=new System.Windows.Media.Imaging.CroppedBitmap(scaled,new Int32Rect((scaled.PixelWidth-width)/2,(scaled.PixelHeight-height)/2,width,height));for(int quality=90;quality>=5;quality-=5){var encoder=new System.Windows.Media.Imaging.JpegBitmapEncoder{QualityLevel=quality};encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(crop));using var stream=new MemoryStream();encoder.Save(stream);if(width!=480||stream.Length<=98304)return stream.ToArray();}throw new IOException("图片无法压缩到设备要求的大小。");}
